using ApiMcpServer.Tools;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// Logs must go to stderr — stdout is the MCP JSON-RPC transport.
builder.Logging.AddConsole(o => o.LogToStandardErrorThreshold = LogLevel.Trace);

// Register HttpClient with a base address for the target REST API.
// Change the BaseAddress to point at your real API.
builder.Services.AddHttpClient<ApiTools>(client =>
{
    client.BaseAddress = new Uri("https://api.example.com");
});

// Wire up the MCP server with stdio transport and register the tool class.
builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithTools<ApiTools>();

await builder.Build().RunAsync();

